// Parse incoming chat data and metadata (prompt specs)
const chatInput = $json.chatInput || '';
const sessionId = $json.sessionId || '';
const files = $json.files || [];

// Parse metadata - handle both string and object formats
let metadata = $json.metadata || {};
if (typeof metadata === 'string') {
  try {
    metadata = JSON.parse(metadata);
  } catch (e) {
    console.error('Failed to parse metadata:', e);
    metadata = {};
  }
}

// Extract customer information (as per prompt specs)
const customerId = metadata.customerId;
const widgetId = metadata.widgetId;
const companyName = metadata.companyName || '';
const userRole = metadata.userRole || 'visitor';
const subscription = metadata.subscription || 'free';

// Default client metadata (as per prompt)
const clientCurrentDateTime = metadata.clientCurrentDateTime || new Date().toISOString();
const clientCurrentTimezone = metadata.clientCurrentTimezone || 'Europe/Istanbul';
const clientQueryParams = metadata.clientQueryParams || {};
const clientUserAgent = metadata.clientUserAgent || '';

// Custom fields from prompt
const customFields = metadata.customFields || {};

// Enhanced metadata with all prompt specifications
const enhancedMetadata = {
  customerId,
  widgetId,
  companyName,
  userRole,
  subscription,
  sessionId,
  timestamp: new Date().toISOString(),
  hasFiles: files.length > 0,
  fileCount: files.length,
  clientCurrentDateTime,
  clientCurrentTimezone,
  clientQueryParams,
  clientUserAgent,
  customFields,
  pageUrl: metadata.pageUrl || '',
  sessionStart: metadata.sessionStart || new Date().toISOString(),
  locale: metadata.locale || 'tr'
};

// Clean and prepare user query
const cleanQuery = chatInput.trim();

// Validate required data (as per prompt specs)
if (!customerId) {
  throw new Error('Customer ID is required');
}

if (!widgetId) {
  throw new Error('Widget ID is required');
}

if (!cleanQuery && files.length === 0) {
  throw new Error('Chat input or files are required');
}

return [{
  json: {
    userQuery: cleanQuery,
    customerId,
    widgetId,
    sessionId,
    files,
    metadata: enhancedMetadata,
    processingTimestamp: Date.now()
  }
}];

// Build context from search results (Turkish language support)
const searchResults = $('Vector Search Documents').item(0).json || [];
const userQuery = $('Parse Chat Input').item(0).json.userQuery;
const metadata = $('Parse Chat Input').item(0).json.metadata;

// Prepare context for AI
let context = '';
let sourceDocuments = [];

if (searchResults.length > 0) {
  context = searchResults.map((result, index) => {
    sourceDocuments.push({
      filename: result.document_filename,
      similarity: result.similarity,
      chunkId: result.chunk_id
    });

    return `[Kaynak ${index + 1} - ${result.document_filename}]\n${result.content}`;
  }).join('\n\n---\n\n');
} else {
  context = 'Üzgünüm, sorgunuzla ilgili spesifik bilgi bulunamadı.';
}

// Prepare Turkish system prompt with company context
const systemPrompt = `Sen ${metadata.companyName || 'şirketimizin'} müşteri hizmetleri asistanısın. Kullanıcının sorularını mevcut dokümanlardaki bilgiler ışığında yanıtla.

Kurallar:
1. Sadece verilen bilgileri kullan
2. Türkçe yanıtla
3. Dostça ve yardımsever ol
4. Bilgin yoksa açıkça söyle
5. Kaynak belgeleri belirt
6. Kısa ve öz yanıtlar ver
7. Kullanıcının ${metadata.userRole} rolünde olduğunu unutma
8. ${metadata.subscription} abonelik seviyesine uygun yanıt ver

Mevcut Bilgiler:
${context}

Şirket: ${metadata.companyName}
Kullanıcı Rolü: ${metadata.userRole}
Abonelik: ${metadata.subscription}
Zaman Dilimi: ${metadata.clientCurrentTimezone}`;

// Prepare conversation history
const messages = [
  {
    role: 'system',
    content: systemPrompt
  },
  {
    role: 'user',
    content: userQuery
  }
];

return [{
  json: {
    messages,
    context,
    sourceDocuments,
    hasContext: searchResults.length > 0,
    userQuery,
    metadata
  }
}];

// Process OpenAI response and prepare final output (as per prompt specs)
const openaiResponse = $('OpenAI Chat Completion').item(0).json;
const contextData = $('Build AI Context').item(0).json;
const metadata = contextData.metadata;

// Extract AI response
const aiMessage = openaiResponse.choices?.[0]?.message?.content || 'Üzgünüm, şu anda yanıt veremiyorum.';

// Calculate response time
const processingStart = $('Parse Chat Input').item(0).json.processingTimestamp;
const responseTime = Date.now() - processingStart;

// Generate follow-up prompts based on context and Turkish language
const followUpPrompts = [];
if (contextData.hasContext) {
  followUpPrompts.push(
    'Bu konuda daha detaylı bilgi alabilir miyim?',
    'Başka hangi konularda yardım edebilirsiniz?',
    'Bu bilgiyle ilgili dokümanları görebilir miyim?'
  );
} else {
  followUpPrompts.push(
    'Hangi konularda yardım edebilirsiniz?',
    'Mevcut dokümanlarda neler var?',
    'Nasıl daha iyi yardım alabilirim?'
  );
}

// Prepare response in N8N Chat format (exact prompt specification)
const response = {
  output: aiMessage,
  followUpPrompts: followUpPrompts,
  metadata: {
    responseTime: `${responseTime}ms`,
    hasContext: contextData.hasContext,
    sourceCount: contextData.sourceDocuments.length,
    timestamp: new Date().toISOString(),
    locale: metadata.locale || 'tr',
    customerId: metadata.customerId,
    widgetId: metadata.widgetId,
    sessionId: metadata.sessionId
  }
};

// Add attachments if sources available (prompt specification)
if (contextData.sourceDocuments.length > 0) {
  response.attachments = contextData.sourceDocuments.map(doc => ({
    type: 'document',
    filename: doc.filename,
    similarity: Math.round(doc.similarity * 100) + '%'
  }));
}

return [{
  json: response
}];

