// Handle file upload processing (as per prompt specs)
const files = $('Parse Chat Input').item(0).json.files;
const customerId = $('Parse Chat Input').item(0).json.customerId;
const widgetId = $('Parse Chat Input').item(0).json.widgetId;
const userQuery = $('Parse Chat Input').item(0).json.userQuery;

// Process each file and extract text
const processedFiles = [];
let extractedText = '';

for (const file of files) {
  // File processing logic would go here
  // For now, we'll simulate file processing
  processedFiles.push({
    name: file.filename || file.name,
    size: file.size,
    type: file.mimeType || file.type,
    url: file.url,
    status: 'processed'
  });

  // Extract text (this would be actual text extraction in real implementation)
  extractedText += `\n\nDosya içeriği (${file.filename || file.name}):\n[Dosya içeriği burada olacak]`;
}

return [{
  json: {
    customerId,
    widgetId,
    userQuery,
    files: processedFiles,
    extractedText: extractedText.trim(),
    processedCount: processedFiles.length
  }
}];

// Merge file content with original query (prompt specification)
const fileProcessingResult = $('Process Uploaded Files').item(0).json;
const originalInput = $('Parse Chat Input').item(0).json;

// Combine file content with original query
let enhancedQuery = originalInput.userQuery;

if (fileProcessingResult.extractedText) {
  enhancedQuery = `Kullanıcı sorusu: ${originalInput.userQuery}\n\nYüklenen dosya içeriği:\n${fileProcessingResult.extractedText}`;
}

// Return enhanced data for further processing
return [{
  json: {
    ...originalInput,
    userQuery: enhancedQuery,
    processedFiles: fileProcessingResult.files || [],
    hasProcessedFiles: true,
    fileProcessingInfo: {
      processedCount: fileProcessingResult.processedCount || 0,
      extractedTextLength: fileProcessingResult.extractedText?.length || 0
    }
  }
}];

// Error handling for the workflow
const error = $json.error || 'Bilinmeyen bir hata oluştu.';
const originalInput = $('Parse Chat Input').first()?.json || {};

// Log error for debugging
console.error('Workflow Error:', {
  error,
  customerId: originalInput.customerId,
  widgetId: originalInput.widgetId,
  query: originalInput.userQuery,
  timestamp: new Date().toISOString()
});

// Prepare user-friendly error response (prompt specification)
const errorResponse = {
  output: 'Üzgünüm, şu anda teknik bir sorun yaşıyoruz. Lütfen birkaç dakika sonra tekrar deneyin.',
  followUpPrompts: [
    'Tekrar deneyin',
    'Farklı bir soru sorun',
    'Destek ile iletişime geçin'
  ],
  metadata: {
    error: true,
    timestamp: new Date().toISOString(),
    locale: originalInput.metadata?.locale || 'tr',
    customerId: originalInput.customerId,
    widgetId: originalInput.widgetId
  }
};

return [{
  json: errorResponse
}];
